import React, { useState, useEffect } from "react";
import { Menu, Grid } from "antd";
import { NavLink, useHistory } from "react-router-dom"; // Import useHistory for redirection
import { logoutUser } from "../actions/authActions";
import { connect } from "react-redux";
import { Roles } from "../Roles/roles";
import { useLocation } from 'react-router-dom'; // Get current location

const { useBreakpoint } = Grid;

const LeftMenu = (props) => {
  const [isAuthenticated, setisAuthenticated] = useState(false);
  const location = useLocation();
  const history = useHistory(); // Get history object for navigation

  const role = props.userInfo.role;

  // Check if the user is authenticated
  useEffect(() => {
    setisAuthenticated(props.isAuthenticated);

    // If the user is authenticated and not on the /dash route, redirect to /dash
    if (props.isAuthenticated && location.pathname !== "/dash") {
      history.push("/dash");
    }
  }, [props, location, history]);

  const signOut = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("userProfile");
    localStorage.removeItem("profileID");
    props.signOut();
  };

  const handleProfile = () => {};

  const { md } = useBreakpoint();
  const homeRoute = isAuthenticated ? "/dash" : "signin";
  const testRoute = isAuthenticated ? "/attempt-test" : "signup";
  const resultRoute = isAuthenticated ? "/result" : "";
  const signOutRoute = isAuthenticated ? "/" : "";
  const profileRoute = isAuthenticated ? "/profile" : "";
  const createTestRoute = isAuthenticated ? "/create-test" : "";
  const assignedTestRoute = isAuthenticated ? "/assigned-test" : "";

  const style = {
    display: location.pathname === "/start-test" ? "none" : "block",
  };

  return (
    <div className="menu" style={style}>
      <Menu mode={md ? "horizontal" : "inline"}>
        <Menu.Item key="01">
          <NavLink to={homeRoute}>
            {isAuthenticated ? "Home" : "Sign In"}
          </NavLink>
        </Menu.Item>
        <Menu.Item key="02">
          <NavLink to={Roles.teacher === role ? createTestRoute : testRoute}>
            {isAuthenticated
              ? Roles.teacher === role
                ? "Create Test"
                : "Attempt Test"
              : "SignUp"}
          </NavLink>
        </Menu.Item>
        <Menu.Item key="03" className={!isAuthenticated ? "display-none" : ""}>
          <NavLink
            to={Roles.teacher === role ? assignedTestRoute : resultRoute}
          >
            {isAuthenticated
              ? Roles.teacher === role
                ? "Assigned Test"
                : "Result"
              : ""}
          </NavLink>
        </Menu.Item>
        <Menu.Item key="05" className={!isAuthenticated ? "display-none" : ""}>
          <NavLink to={profileRoute} onClick={handleProfile}>
            {isAuthenticated ? "Profile" : ""}
          </NavLink>
        </Menu.Item>
      </Menu>
      <div className="right-side">
        <NavLink
          to={signOutRoute}
          onClick={signOut}
          className={!isAuthenticated ? "display-none signout" : "signout"}
        >
          {isAuthenticated ? "Sign Out" : ""}
        </NavLink>
      </div>
    </div>
  );
};

const mapStateToProps = (state) => {
  return {
    isAuthenticated: state.auth.isAuthenticated,
    userInfo: state.auth.user,
  };
};

const mapDispatchToProps = (dispatch) => {
  return {
    signOut: () => dispatch(logoutUser()),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(LeftMenu);
